CREATE TABLE recurrence_rules (id VARCHAR(36) NOT NULL, owner_id VARCHAR(36) NOT NULL, type VARCHAR(20) NOT NULL, description VARCHAR(255) NOT NULL, amount DECIMAL(19,2) NOT NULL, category_id VARCHAR(36) NOT NULL, account_id VARCHAR(36) NOT NULL, frequency VARCHAR(20) NOT NULL, start_date DATE NOT NULL, end_date DATE, due_day TINYINT NOT NULL, status VARCHAR(20) NOT NULL, created_at TIMESTAMP(6) NOT NULL, updated_at TIMESTAMP(6) NOT NULL, version BIGINT NULL, PRIMARY KEY(id), CONSTRAINT ck_recurrence_amount CHECK(amount > 0), CONSTRAINT ck_recurrence_day CHECK(due_day BETWEEN 1 AND 31), CONSTRAINT fk_recurrence_category FOREIGN KEY(category_id) REFERENCES categories(id), CONSTRAINT fk_recurrence_account FOREIGN KEY(account_id) REFERENCES asset_accounts(id));
CREATE INDEX idx_recurrence_owner_status ON recurrence_rules(owner_id,status); CREATE INDEX idx_recurrence_owner_start ON recurrence_rules(owner_id,start_date);
